insert into problems(lesson_id,sort,title,input,output,solution,explanation,solution2,explanation2) values
(212,199,E'Safe calculator',E'10 / 0',E'Error: division by zero',E'a, op, b = input().split()\nops = {''+'': lambda x, y: x + y, ''-'': lambda x, y: x - y, ''*'': lambda x, y: x * y, ''/'': lambda x, y: x / y}\ntry:\n    print(ops[op](float(a), float(b)))\nexcept ZeroDivisionError:\n    print(''Error: division by zero'')\nexcept KeyError:\n    print(''Error: unknown operator'')',E'వేర్వేరు errors కి వేర్వేరు except blocks.',E'import operator as o\na, op, b = input().split()\nf = {''+'': o.add, ''-'': o.sub, ''*'': o.mul, ''/'': o.truediv}\nx, y = float(a), float(b)\nif op not in f:\n    print(''Error: unknown operator'')\nelif op == ''/'' and y == 0:\n    print(''Error: division by zero'')\nelse:\n    print(f[op](x, y))',E'LBYL: ముందే conditions check చేసి error రాకుండా చూశాం.'),
(212,200,E'Collect all validation errors',E'Nihar -5 abc',E'[''age out of range'', ''email invalid'']',E'name, age, email = input().split()\nerrors = []\ndef chk_age(a):\n    if not 0 <= int(a) <= 120:\n        raise ValueError(''age out of range'')\ndef chk_email(e):\n    if ''@'' not in e:\n        raise ValueError(''email invalid'')\nfor f, v in ((chk_age, age), (chk_email, email)):\n    try:\n        f(v)\n    except ValueError as e:\n        errors.append(str(e))\nprint(errors)',E'ఒక్కో validator error raise చేస్తుంది; అన్నీ collect చేశాం (మొదటి error దగ్గర ఆపలేదు).',E'name, age, email = input().split()\nerrors = []\nif not age.lstrip(''-'').isdigit() or not 0 <= int(age) <= 120:\n    errors.append(''age out of range'')\nif ''@'' not in email:\n    errors.append(''email invalid'')\nprint(errors)',E'Simple if checks; exceptions లేకుండా.'),
(212,201,E'Exception chaining',E'{"port": "80x"}',E'ConfigError: invalid port (caused by ValueError)',E'import json\nclass ConfigError(Exception):\n    pass\ncfg = json.loads(input())\ntry:\n    try:\n        int(cfg[''port''])\n    except ValueError as e:\n        raise ConfigError(''invalid port'') from e\nexcept ConfigError as e:\n    print(f''ConfigError: {e} (caused by {type(e.__cause__).__name__})'')',E'raise ... from e అసలు కారణాన్ని __cause__ లో ఉంచుతుంది.',E'import json\nclass ConfigError(Exception):\n    def __init__(self, msg, cause):\n        super().__init__(msg)\n        self.cause = cause\ncfg = json.loads(input())\ntry:\n    try:\n        int(cfg[''port''])\n    except ValueError as e:\n        raise ConfigError(''invalid port'', e)\nexcept ConfigError as e:\n    print(f''ConfigError: {e} (caused by {type(e.cause).__name__})'')',E'Cause ని మనమే attribute గా దాచాం.'),
(212,202,E'Transaction rollback',E'100\n-30 -50 -40',E'100',E'bal = int(input())\nops = list(map(int, input().split()))\nsaved = bal\ntry:\n    for o in ops:\n        if bal + o < 0:\n            raise ValueError(''insufficient'')\n        bal += o\nexcept ValueError:\n    bal = saved\nprint(bal)',E'ముందు state save; error వస్తే restore (all-or-nothing).',E'bal = int(input())\nops = list(map(int, input().split()))\nclass Tx:\n    def __enter__(self):\n        self.saved = bal\n        return self\n    def __exit__(self, t, v, tb):\n        global bal\n        if t:\n            bal = self.saved\n        return True\nwith Tx():\n    for o in ops:\n        if bal + o < 0:\n            raise ValueError(''insufficient'')\n        bal += o\nprint(bal)',E'Context manager: error అయితే __exit__ లో rollback.'),
(212,203,E'First valid number in range',E'abc 200 -1 42 7',E'42',E'for t in input().split():\n    try:\n        v = int(t)\n        if 0 <= v <= 100:\n            print(v)\n            break\n    except ValueError:\n        continue',E'Invalid tokens ని skip చేస్తూ మొదటి valid దగ్గర break.',E'def ok(t):\n    try:\n        v = int(t)\n    except ValueError:\n        return False\n    return 0 <= v <= 100\nprint(next((int(t) for t in input().split() if ok(t)), ''none''))',E'Helper ok() + next(generator, default).'),
(212,204,E'Cleanup order with finally',E'2',E'enter 2\nenter 1\ncleanup 1\ncleanup 2\ncaught',E'def f(k):\n    print(''enter'', k)\n    try:\n        if k == 1:\n            raise RuntimeError(''boom'')\n        f(k - 1)\n    finally:\n        print(''cleanup'', k)\ntry:\n    f(int(input()))\nexcept RuntimeError:\n    print(''caught'')',E'Exception పైకి వెళ్ళేటప్పుడు ప్రతి level finally run అవుతుంది (లోపలి నుండి).',E'from contextlib import ExitStack\ntry:\n    with ExitStack() as st:\n        for k in range(int(input()), 0, -1):\n            print(''enter'', k)\n            st.callback(print, ''cleanup'', k)\n        raise RuntimeError(''boom'')\nexcept RuntimeError:\n    print(''caught'')',E'ExitStack callbacks LIFO order లో run అవుతాయి.'),
(213,205,E'Log level counts',E'5\nINFO start\nERROR disk\nINFO ok\nERROR net\nWARN slow',E'{''INFO'': 2, ''ERROR'': 2, ''WARN'': 1}',E'from collections import Counter\nn = int(input())\nlines = [input() for _ in range(n)]\nwith open(''log.txt'', ''w'') as f:\n    f.write(''\\n''.join(lines))\nwith open(''log.txt'') as f:\n    print(dict(Counter(l.split()[0] for l in f.read().splitlines())))',E'File రాసి చదివి, మొదటి word తో Counter.',E'from collections import defaultdict\nn = int(input())\nwith open(''log.txt'', ''w'') as f:\n    for _ in range(n):\n        f.write(input() + ''\\n'')\nd = defaultdict(int)\nwith open(''log.txt'') as f:\n    for line in f:\n        d[line.split()[0]] += 1\nprint(dict(d))',E'File ని line by line stream చేశాం (memory save).'),
(213,206,E'Top 2 words from file',E'the cat and the hat and the bat',E'[(''the'', 3), (''and'', 2)]',E'from collections import Counter\nwith open(''w.txt'', ''w'') as f:\n    f.write(input())\nwith open(''w.txt'') as f:\n    print(Counter(f.read().split()).most_common(2))',E'most_common(k) frequency ప్రకారం top k.',E'with open(''w.txt'', ''w'') as f:\n    f.write(input())\nd = {}\nwith open(''w.txt'') as f:\n    for w in f.read().split():\n        d[w] = d.get(w, 0) + 1\nprint(sorted(d.items(), key=lambda x: -x[1])[:2])',E'Manual dict + stable sort (-count).'),
(213,207,E'JSON file nested update',E'{"a": 1, "b": {"c": 2}}',E'{"a": 1, "b": {"c": 3}}',E'import json\nd = json.loads(input())\nwith open(''d.json'', ''w'') as f:\n    json.dump(d, f)\nwith open(''d.json'') as f:\n    d = json.load(f)\nd[''b''][''c''] += 1\nprint(json.dumps(d))',E'dump → load round trip తర్వాత nested value మార్చాం.',E'import json\nraw = input()\nwith open(''d.json'', ''w'') as f:\n    f.write(raw)\nwith open(''d.json'') as f:\n    d = json.loads(f.read())\nd[''b''].update(c=d[''b''][''c''] + 1)\nprint(json.dumps(d))',E'write/read + loads/dumps; nested dict.update.'),
(213,208,E'CSV average per student',E'4\nAlice,Math,80\nBob,Math,70\nAlice,Sci,90\nBob,Sci,60',E'{''Alice'': 85.0, ''Bob'': 65.0}',E'import csv\nn = int(input())\nrows = [input() for _ in range(n)]\nwith open(''s.csv'', ''w'', newline='''') as f:\n    f.write(''\\n''.join(rows) + ''\\n'')\ng = {}\nwith open(''s.csv'') as f:\n    for name, sub, m in csv.reader(f):\n        g.setdefault(name, []).append(int(m))\nprint({k: sum(v) / len(v) for k, v in g.items()})',E'csv.reader rows; పేరు వారీగా marks lists.',E'import csv\nfrom collections import defaultdict\nn = int(input())\nrows = [''name,subject,marks''] + [input() for _ in range(n)]\nwith open(''s.csv'', ''w'') as f:\n    f.write(''\\n''.join(rows))\ntot, cnt = defaultdict(float), defaultdict(int)\nwith open(''s.csv'') as f:\n    for r in csv.DictReader(f):\n        tot[r[''name'']] += int(r[''marks''])\n        cnt[r[''name'']] += 1\nprint({k: tot[k] / cnt[k] for k in tot})',E'DictReader: header తో columns పేర్లు; totals/counts.'),
(213,209,E'Last k lines of a file',E'5 2\na\nb\nc\nd\ne',E'd\ne',E'from collections import deque\nn, k = map(int, input().split())\nwith open(''t.txt'', ''w'') as f:\n    for _ in range(n):\n        f.write(input() + ''\\n'')\nwith open(''t.txt'') as f:\n    print(*(l.strip() for l in deque(f, maxlen=k)), sep=''\\n'')',E'deque(maxlen=k) streaming: file మొత్తం memory లో లేదు.',E'n, k = map(int, input().split())\nwith open(''t.txt'', ''w'') as f:\n    for _ in range(n):\n        f.write(input() + ''\\n'')\nwith open(''t.txt'') as f:\n    print(*[l.strip() for l in f.readlines()[-k:]], sep=''\\n'')',E'readlines() మొత్తం load చేసి చివరి k slice.'),
(213,210,E'Merge two sorted files',E'1 3 5\n2 4 6',E'1 2 3 4 5 6',E'a = input().split()\nb = input().split()\nfor name, v in ((''a.txt'', a), (''b.txt'', b)):\n    with open(name, ''w'') as f:\n        f.write(''\\n''.join(v))\nA = [int(x) for x in open(''a.txt'').read().split()]\nB = [int(x) for x in open(''b.txt'').read().split()]\ni = j = 0\nout = []\nwhile i < len(A) and j < len(B):\n    if A[i] <= B[j]:\n        out.append(A[i])\n        i += 1\n    else:\n        out.append(B[j])\n        j += 1\nout += A[i:] + B[j:]\nprint(*out)',E'Two-pointer merge: చిన్నది ముందు.',E'a = input().split()\nb = input().split()\nfor name, v in ((''a.txt'', a), (''b.txt'', b)):\n    with open(name, ''w'') as f:\n        f.write(''\\n''.join(v))\nimport heapq\nprint(*heapq.merge(*[map(int, open(n).read().split()) for n in (''a.txt'', ''b.txt'')]))',E'heapq.merge lazily merge చేస్తుంది.'),
(213,211,E'Duplicate lines (first-seen order)',E'5\nx\ny\nx\nz\ny',E'[''x'', ''y'']',E'n = int(input())\nwith open(''l.txt'', ''w'') as f:\n    for _ in range(n):\n        f.write(input() + ''\\n'')\nseen, dup = set(), []\nwith open(''l.txt'') as f:\n    for line in f:\n        line = line.strip()\n        if line in seen and line not in dup:\n            dup.append(line)\n        seen.add(line)\nprint(dup)',E'Set లో చూసినవి; రెండోసారి వస్తే dup లో.',E'from collections import Counter\nn = int(input())\nwith open(''l.txt'', ''w'') as f:\n    for _ in range(n):\n        f.write(input() + ''\\n'')\nwith open(''l.txt'') as f:\n    c = Counter(l.strip() for l in f)\nprint([k for k, v in c.items() if v > 1])',E'Counter తో count > 1.'),
(213,212,E'Config parser with types',E'4\n# comment\nport=80\ndebug=true\nname=app',E'{''port'': 80, ''debug'': True, ''name'': ''app''}',E'n = int(input())\nwith open(''c.ini'', ''w'') as f:\n    for _ in range(n):\n        f.write(input() + ''\\n'')\ncfg = {}\nwith open(''c.ini'') as f:\n    for line in f:\n        line = line.strip()\n        if not line or line.startswith(''#''):\n            continue\n        k, v = line.split(''='', 1)\n        cfg[k] = int(v) if v.isdigit() else (v == ''true'' if v in (''true'', ''false'') else v)\nprint(cfg)',E'Comments, ఖాళీ lines skip; value type అంచనా.',E'n = int(input())\nwith open(''c.ini'', ''w'') as f:\n    for _ in range(n):\n        f.write(input() + ''\\n'')\ndef conv(v):\n    if v in (''true'', ''false''):\n        return v == ''true''\n    try:\n        return int(v)\n    except ValueError:\n        return v\nlines = [l.strip() for l in open(''c.ini'') if l.strip() and not l.startswith(''#'')]\nprint({k: conv(v) for k, v in (l.split(''='', 1) for l in lines)})',E'conv() helper: bool, int, లేకపోతే string.'),
(213,213,E'Line numbers containing a word',E'4 fox\nthe quick brown\nfox jumps\nlazy dog\nfox again',E'[2, 4]',E'n, w = input().split()\nwith open(''f.txt'', ''w'') as f:\n    for _ in range(int(n)):\n        f.write(input() + ''\\n'')\nwith open(''f.txt'') as f:\n    print([i for i, l in enumerate(f, 1) if w in l.split()])',E'enumerate(f, 1) తో line numbers.',E'import re\nn, w = input().split()\nwith open(''f.txt'', ''w'') as f:\n    for _ in range(int(n)):\n        f.write(input() + ''\\n'')\nwith open(''f.txt'') as f:\n    lines = f.read().splitlines()\nprint([i + 1 for i, l in enumerate(lines) if re.search(r''\\b'' + re.escape(w) + r''\\b'', l)])',E'Regex word boundary \\b.'),
(213,214,E'Binary file length and byte sum',E'hello',E'5 532',E't = input()\nwith open(''b.bin'', ''wb'') as f:\n    f.write(t.encode())\nwith open(''b.bin'', ''rb'') as f:\n    d = f.read()\nprint(len(d), sum(d))',E'''wb''/''rb'' modes; bytes iterate చేస్తే ints.',E't = input()\nwith open(''b.bin'', ''wb'') as f:\n    f.write(t.encode())\ntotal = n = 0\nwith open(''b.bin'', ''rb'') as f:\n    while chunk := f.read(2):\n        n += len(chunk)\n        total += sum(chunk)\nprint(n, total)',E'Chunks గా చదివాం: పెద్ద files కి సరైన పద్ధతి.'),
(214,215,E'Business days between dates',E'2024-03-01\n2024-03-15',E'10',E'from datetime import date, timedelta\na = date.fromisoformat(input())\nb = date.fromisoformat(input())\nn = 0\nwhile a < b:\n    n += a.weekday() < 5\n    a += timedelta(1)\nprint(n)',E'weekday() < 5 అంటే Mon–Fri; రోజు రోజుకీ ముందుకు.',E'from datetime import date, timedelta\na = date.fromisoformat(input())\nb = date.fromisoformat(input())\nprint(sum((a + timedelta(i)).weekday() < 5 for i in range((b - a).days)))',E'రోజుల range మీద generator sum; loop mutate లేదు.'),
(214,216,E'Count valid emails',E'a@b.com bad@ x.y@z.org @no',E'2',E'import re\nprint(sum(bool(re.fullmatch(r''[\\w.]+@\\w+\\.[a-z]+'', t)) for t in input().split()))',E'fullmatch మొత్తం token pattern కి సరిపోవాలి.',E'def ok(t):\n    p = t.split(''@'')\n    return len(p) == 2 and p[0] != '''' and ''.'' in p[1] and all(p[1].split(''.''))\nprint(sum(map(ok, input().split())))',E'Regex లేకుండా split తో manual validation.'),
(214,217,E'Josephus problem',E'7 3',E'4',E'from collections import deque\nn, k = map(int, input().split())\nd = deque(range(1, n + 1))\nwhile len(d) > 1:\n    d.rotate(-(k - 1))\n    d.popleft()\nprint(d[0])',E'deque.rotate తో k-1 మందిని వెనక్కి పంపి k వ వ్యక్తిని తొలగిస్తాం.',E'n, k = map(int, input().split())\nl = list(range(1, n + 1))\ni = 0\nwhile len(l) > 1:\n    i = (i + k - 1) % len(l)\n    l.pop(i)\nprint(l[0])',E'List + index modulo; pop(i) O(n).'),
(214,218,E'Next Friday the 13th',E'2024-03-01',E'2024-09-13',E'from datetime import date, timedelta\nd = date.fromisoformat(input())\nwhile True:\n    d += timedelta(1)\n    if d.day == 13 and d.weekday() == 4:\n        print(d)\n        break',E'రోజు రోజుకీ ముందుకు వెళ్ళి check.',E'from datetime import date\ny, m, _ = map(int, input().split(''-''))\nwhile True:\n    m += 1\n    if m > 12:\n        y, m = y + 1, 1\n    if date(y, m, 13).weekday() == 4:\n        print(date(y, m, 13))\n        break',E'నెల నెలకీ 13వ తేదీ మాత్రమే check: వేగం.'),
(214,219,E'Deep merge JSON',E'{"a": 1, "b": {"c": 2}}\n{"b": {"d": 3}, "e": 4}',E'{"a": 1, "b": {"c": 2, "d": 3}, "e": 4}',E'import json\ndef merge(a, b):\n    for k, v in b.items():\n        if isinstance(v, dict) and isinstance(a.get(k), dict):\n            merge(a[k], v)\n        else:\n            a[k] = v\n    return a\nprint(json.dumps(merge(json.loads(input()), json.loads(input()))))',E'Nested dicts కి recursion.',E'import json\na = json.loads(input())\nb = json.loads(input())\nst = [(a, b)]\nwhile st:\n    x, y = st.pop()\n    for k, v in y.items():\n        if isinstance(v, dict) and isinstance(x.get(k), dict):\n            st.append((x[k], v))\n        else:\n            x[k] = v\nprint(json.dumps(a))',E'Explicit stack: recursion depth సమస్య లేదు.'),
(214,220,E'Sum amounts in text',E'paid 120 and 80.5 then 20',E'220.5',E'import re\nprint(sum(float(x) for x in re.findall(r''\\d+(?:\\.\\d+)?'', input())))',E'Regex తో numbers వెలికితీత.',E'tot = 0\nfor t in input().split():\n    try:\n        tot += float(t)\n    except ValueError:\n        pass\nprint(tot)',E'ప్రతి token float చేసి చూశాం; fail అయితే skip.'),
(214,221,E'Most common word',E'The cat. the Hat, THE bat!',E'the 3',E'import re\nfrom collections import Counter\nw, c = Counter(re.findall(r''[a-z]+'', input().lower())).most_common(1)[0]\nprint(w, c)',E'lower చేసి letters మాత్రమే; Counter.',E'import string\nt = input().lower().translate(str.maketrans('''', '''', string.punctuation))\nd = {}\nfor w in t.split():\n    d[w] = d.get(w, 0) + 1\nw = max(d, key=d.get)\nprint(w, d[w])',E'Punctuation తొలగించి manual count.'),
(214,222,E'Dice sum ways',E'10',E'27',E'from itertools import product\nn = int(input())\nprint(sum(sum(r) == n for r in product(range(1, 7), repeat=3)))',E'3 dice అన్ని 216 combinations check.',E'n = int(input())\nways = [1] + [0] * n\nfor _ in range(3):\n    nw = [0] * (n + 1)\n    for s in range(n + 1):\n        for d in range(1, 7):\n            if s + d <= n:\n                nw[s + d] += ways[s]\n    ways = nw\nprint(ways[n])',E'DP: ప్రతి dice తర్వాత sum ways table.'),
(214,223,E'GCD and LCM of list',E'12 18 24',E'6 72',E'import math\nfrom functools import reduce\na = list(map(int, input().split()))\nprint(reduce(math.gcd, a), reduce(math.lcm, a))',E'math.gcd/lcm + reduce.',E'def g(a, b):\n    while b:\n        a, b = b, a % b\n    return a\na = list(map(int, input().split()))\ng0 = l0 = a[0]\nfor x in a[1:]:\n    g0 = g(g0, x)\n    l0 = l0 * x // g(l0, x)\nprint(g0, l0)',E'Euclid algorithm; lcm = a*b/gcd.'),
(214,224,E'Path parts',E'/home/user/docs/file.tar.gz',E'file.tar.gz .gz /home/user/docs',E'import os\np = input()\nprint(os.path.basename(p), os.path.splitext(p)[1], os.path.dirname(p))',E'os.path functions.',E'from pathlib import PurePosixPath\np = PurePosixPath(input())\nprint(p.name, p.suffix, p.parent)',E'pathlib object properties.'),
(215,225,E'SQL group by',E'Alice 50 Bob 30 Alice 20',E'[(''Alice'', 70), (''Bob'', 30)]',E'import sqlite3\nt = input().split()\nc = sqlite3.connect('':memory:'')\nc.execute(''CREATE TABLE s(name TEXT, amt INT)'')\nc.executemany(''INSERT INTO s VALUES (?, ?)'', [(t[i], int(t[i + 1])) for i in range(0, len(t), 2)])\nprint(c.execute(''SELECT name, SUM(amt) FROM s GROUP BY name ORDER BY name'').fetchall())',E'GROUP BY + SUM per-name totals.',E't = input().split()\nd = {}\nfor i in range(0, len(t), 2):\n    d[t[i]] = d.get(t[i], 0) + int(t[i + 1])\nprint(sorted(d.items()))',E'SQL లేకుండా dict తో అదే aggregate.'),
(215,226,E'Merge sorted lists (heapq)',E'1 4 7\n2 5\n3 6 8',E'[1, 2, 3, 4, 5, 6, 7, 8]',E'import heapq\nL = [list(map(int, input().split())) for _ in range(3)]\nprint(list(heapq.merge(*L)))',E'heapq.merge sorted inputs ని lazily merge చేస్తుంది.',E'import heapq\nL = [list(map(int, input().split())) for _ in range(3)]\nh = [(l[0], i, 0) for i, l in enumerate(L) if l]\nheapq.heapify(h)\nout = []\nwhile h:\n    v, i, j = heapq.heappop(h)\n    out.append(v)\n    if j + 1 < len(L[i]):\n        heapq.heappush(h, (L[i][j + 1], i, j + 1))\nprint(out)',E'Manual k-way merge: heap లో (value, list, position).'),
(215,227,E'Count in range (bisect)',E'1 3 5 7 9\n3 7',E'3',E'from bisect import bisect_left, bisect_right\na = list(map(int, input().split()))\nlo, hi = map(int, input().split())\nprint(bisect_right(a, hi) - bisect_left(a, lo))',E'రెండు binary searches తో range count: O(log n).',E'a = list(map(int, input().split()))\nlo, hi = map(int, input().split())\nprint(sum(lo <= x <= hi for x in a))',E'Linear scan O(n) (bisect O(log n) కంటే నెమ్మది).'),
(215,228,E'Top-K words with tie-break',E'b a b c a d a\n3',E'[''a'', ''b'', ''c'']',E'from collections import Counter\nc = Counter(input().split())\nk = int(input())\nprint(sorted(c, key=lambda w: (-c[w], w))[:k])',E'Key (-count, word): count తగ్గుతూ, tie లో alphabetical.',E'import heapq\nfrom collections import Counter\nc = Counter(input().split())\nk = int(input())\nprint(heapq.nsmallest(k, c, key=lambda w: (-c[w], w)))',E'nsmallest O(n log k).'),
(215,229,E'Running median',E'5 2 8 1 9',E'5 3.5 5 3.5 5',E'import heapq\nlo, hi = [], []\nres = []\nfor x in map(int, input().split()):\n    heapq.heappush(lo, -x)\n    heapq.heappush(hi, -heapq.heappop(lo))\n    if len(hi) > len(lo):\n        heapq.heappush(lo, -heapq.heappop(hi))\n    res.append(-lo[0] if len(lo) > len(hi) else (-lo[0] + hi[0]) / 2)\nprint(*res)',E'రెండు heaps: max-heap (కింది సగం), min-heap (పై సగం).',E'from bisect import insort\na = []\nres = []\nfor x in map(int, input().split()):\n    insort(a, x)\n    n = len(a)\n    res.append(a[n // 2] if n % 2 else (a[n // 2 - 1] + a[n // 2]) / 2)\nprint(*res)',E'insort తో sorted list; middle index.'),
(215,230,E'Second highest salary',E'Alice 50 Bob 80 Cara 80 Dan 60',E'60',E'import sqlite3\nt = input().split()\nc = sqlite3.connect('':memory:'')\nc.execute(''CREATE TABLE e(n TEXT, s INT)'')\nc.executemany(''INSERT INTO e VALUES (?, ?)'', [(t[i], int(t[i + 1])) for i in range(0, len(t), 2)])\nprint(c.execute(''SELECT DISTINCT s FROM e ORDER BY s DESC LIMIT 1 OFFSET 1'').fetchone()[0])',E'DISTINCT + ORDER BY DESC + OFFSET 1.',E't = input().split()\nprint(sorted({int(t[i]) for i in range(1, len(t), 2)}, reverse=True)[1])',E'Set తో distinct, sort చేసి index 1.');
